-- HIGH-FIDELITY HOME AUDIO (10 products)
('bluesound-node-x-2026', 'Bluesound NODE X 2026 Wireless Hi-Res Music Streamer - Silver', 'audio', 380000, 369000, 315000, 5, 1.25, '/assets/products/bluesound-node-x.jpg', 'Transform any stereo system into a modern streaming powerhouse. The NODE X features an ESS Sabre ES9039Q2M flagship DAC, THX AAA headphone amplifier, and BluOS multi-room control, decoding MQA, FLAC, and DSD files for an audiophile-grade listening experience.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/bluesound-node-x.jpg', 348000, 4.7, 1, 'Bluesound', 1, 1),

('audioengine-hd6-premium', 'Audioengine HD6 Premium Powered Bookshelf Speakers - Walnut Veneer', 'audio', 480000, 469000, 410000, 4, 9.5, '/assets/products/audioengine-hd6.jpg', 'Handcrafted real walnut veneer cabinets house 5.5-inch Kevlar woofers and 1-inch silk dome tweeters, driven by dual 75W Class A/B amplifiers. Built-in Bluetooth aptX-HD, 24-bit DAC, and analog inputs create a complete, no-compromise audio system.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/audioengine-hd6.jpg', 438000, 4.8, 0, 'Audioengine', 1, 1),

('klipsch-the-sevens', 'Klipsch The Sevens Heritage Powered Speakers - Black Ash', 'audio', 650000, 639000, 555000, 4, 11.2, '/assets/products/klipsch-the-sevens.jpg', 'Klipsch legendary horn-loaded tweeters meet modern connectivity. The Sevens feature a 192kHz/24-bit DAC, HDMI-ARC for TV integration, phono preamp for turntables, and 200W of bi-amplified digital power delivering the live-concert dynamics Klipsch is famous for.', 1, unixepoch('2026-06-16'), 1, 555000, '/assets/products/klipsch-the-sevens.jpg', 605000, 4.7, 0, 'Klipsch', 1, 1),

('wiim-ultra-streamer', 'WiiM Ultra Audiophile Music Streamer with Touchscreen & Room Correction', 'audio', 185000, 179000, 148000, 8, 0.85, '/assets/products/wiim-ultra.jpg', 'Room-perfect audio at an accessible price. The WiiM Ultra features a vibrant 3.5-inch touchscreen, per-channel room correction that eliminates acoustic problems, a premium AKM DAC, and a phono input for vinyl enthusiasts—all in a sleek aluminum chassis.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/wiim-ultra.jpg', 168000, 4.7, 1, 'WiiM', 1, 1),

('pro-ject-debut-carbon-evo-2', 'Pro-Ject Debut Carbon EVO 2 Audiophile Turntable - Satin Blue', 'audio', 480000, 469000, 410000, 3, 6.0, '/assets/products/project-evo-2.jpg', 'Handmade in the Czech Republic, the EVO 2 features a one-piece carbon fiber tonearm, an acoustically inert MDF plinth, and an Ortofon 2M Red moving magnet cartridge. Electronic speed change and isolated motor deliver audiophile vinyl playback without compromise.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/project-evo-2.jpg', 438000, 4.8, 0, 'Pro-Ject', 1, 1),

('yamaha-r-n1000a-receiver', 'Yamaha R-N1000A Network Hi-Fi Receiver with HDMI & YPAO - Silver', 'audio', 850000, 829000, 720000, 3, 11.8, '/assets/products/yamaha-rn1000a.jpg', 'Yamaha''s decades of audio engineering in one magnificent component. The R-N1000A delivers 100W per channel of pure, dynamic sound with YPAO room calibration, MusicCast multi-room streaming, and HDMI-ARC for seamless TV integration.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/yamaha-rn1000a.jpg', 780000, 4.7, 0, 'Yamaha', 1, 1),

('topping-dx9-pro-dac', 'Topping DX9 PRO+ Desktop DAC & Headphone Amplifier - Black', 'audio', 480000, 469000, 410000, 4, 1.85, '/assets/products/topping-dx9-pro.jpg', 'State-of-the-art measurements from China''s leading DAC manufacturer. Dual ES9039PRO chips deliver 135dB SNR, while the NFCA amplifier outputs 7.5W into 32 ohms—enough power for any headphone. XLR, RCA, and Bluetooth LDAC connectivity complete the package.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/topping-dx9-pro.jpg', 438000, 4.8, 0, 'Topping', 1, 1),

('sennheiser-iem-ie900', 'Sennheiser IE 900 Audiophile In-Ear Monitors - Precision Aluminum', 'audio', 850000, 829000, 720000, 3, 0.12, '/assets/products/sennheiser-ie900.jpg', 'Sennheiser''s flagship IEMs, precision-milled from a single block of aluminum in Germany. The X3R triple-chamber absorber eliminates masking resonances, revealing an astonishingly detailed, holographic soundstage from a single 7mm dynamic driver.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/sennheiser-ie900.jpg', 780000, 4.9, 0, 'Sennheiser', 1, 1),

('hifiman-svanar-wireless', 'HiFiMAN Svanar Wireless ANC True Wireless Earbuds - Silver', 'audio', 380000, 369000, 315000, 4, 0.08, '/assets/products/hifiman-svanar-tws.jpg', 'HiFiMAN''s audiophile expertise enters the TWS world. The Svanar Wireless features a built-in R2R DAC architecture rarely seen in wireless earbuds, delivering organic, analog-like sound with active noise cancellation in a luxury carbon fiber and metal design.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/hifiman-svanar-tws.jpg', 348000, 4.6, 0, 'HiFiMAN', 1, 1),

('denon-perl-pro', 'Denon PerL Pro Personalized ANC Earbuds with Masimo AAT - Black', 'audio', 280000, 275000, 235000, 5, 0.06, '/assets/products/denon-perl-pro.jpg', 'Sound that adapts to your unique hearing. Masimo Adaptive Acoustic Technology measures your ear''s response to create a personalized sound profile, while adaptive ANC, spatial audio, and Denon''s 110-year audio heritage deliver a one-of-a-kind listening experience.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/denon-perl-pro.jpg', 258000, 4.6, 1, 'Denon', 1, 1),

-- ADVANCED SMART HOME SENSORS & AUTOMATION (10 products)
('eve-room-indoor-sensor-3', 'Eve Room 3 Indoor Air Quality Monitor with Thread & Matter - White', 'smart-home', 85000, 82900, 68000, 10, 0.18, '/assets/products/eve-room-3.jpg', 'Know exactly what you''re breathing. The Eve Room 3 tracks VOC concentration, temperature, humidity, and CO2 levels with an e-ink display that updates in real-time. Thread and Matter support ensure compatibility with every major smart home platform.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/eve-room-3.jpg', 78000, 4.5, 1, 'Eve', 1, 1),

('aqara-fp3-presence-sensor', 'Aqara FP3 mmWave Presence Sensor with Zone Positioning - White', 'smart-home', 38000, 36900, 30500, 15, 0.08, '/assets/products/aqara-fp3.jpg', 'Beyond motion—this sensor detects human presence even when sitting completely still. mmWave radar technology with zone positioning creates up to 30 detection zones, enabling automations that follow you through the house without false triggers from pets.', 1, unixepoch('2026-06-16'), 1, 30500, '/assets/products/aqara-fp3.jpg', 34800, 4.6, 1, 'Aqara', 1, 1),

('shelly-pro-4pm-relay', 'Shelly Pro 4PM 4-Channel Smart Relay with Energy Monitoring', 'smart-home', 58000, 55900, 46000, 12, 0.22, '/assets/products/shelly-pro-4pm.jpg', 'Professional-grade smart automation for electricians and serious DIYers. The Pro 4PM controls four independent circuits with precise power monitoring per channel, Ethernet and WiFi connectivity, and local scripting that runs even without internet access.', 1, unixepoch('2026-06-16'), 1, 46000, '/assets/products/shelly-pro-4pm.jpg', 52500, 4.7, 0, 'Shelly', 1, 1),

('flic-twist-smart-button', 'Flic Twist Smart Button with Haptic Feedback & Matter - White', 'smart-home', 45000, 43900, 36500, 18, 0.06, '/assets/products/flic-twist.jpg', 'A physical dial that controls your entire smart home. Twist to dim lights, change thermostat temperature, or scroll through Spotify playlists. Haptic feedback confirms every action, and Matter-over-Thread support ensures it works with Apple, Google, Amazon, and Samsung.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/flic-twist.jpg', 41500, 4.4, 0, 'Flic', 1, 1),

('sensibo-airq-pro', 'Sensibo AirQ Pro Smart AC Controller with Air Quality Sensor - White', 'smart-home', 95000, 92900, 78000, 15, 0.12, '/assets/products/sensibo-airq-pro.jpg', 'Transform any air conditioner into an intelligent climate system. The AirQ Pro controls your AC via infrared while monitoring CO2, PM2.5, VOCs, temperature, and humidity, automatically adjusting settings to maintain healthy air and save up to 40% on electricity.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/sensibo-airq-pro.jpg', 88000, 4.5, 1, 'Sensibo', 1, 1),

('meross-smart-water-shutoff', 'Meross Smart Water Shutoff Valve Controller with Leak Sensor', 'smart-home', 45000, 43900, 36500, 12, 0.35, '/assets/products/meross-water-shutoff.jpg', 'Prevent catastrophic water damage before it starts. This motorized controller attaches to your existing water shutoff valve and automatically closes it when the included leak sensor detects moisture. Alexa, Google, and Apple Home compatible.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/meross-water-shutoff.jpg', 41500, 4.5, 0, 'Meross', 1, 1),

('netatmo-smart-smoke-alarm', 'Netatmo Smart Smoke & Carbon Monoxide Alarm with 10-Year Battery', 'smart-home', 85000, 82900, 68000, 10, 0.28, '/assets/products/netatmo-smoke-alarm.jpg', 'A decade of protection without changing batteries. This intelligent alarm self-tests its sensors and battery weekly, sends smartphone alerts even when you''re away, and silences false alarms from cooking smoke with a wave of your hand.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/netatmo-smoke-alarm.jpg', 78000, 4.6, 0, 'Netatmo', 1, 1),

('yale-assure-lock-3', 'Yale Assure Lock 3 Keyless Touchscreen Deadbolt with Matter', 'smart-home', 165000, 159000, 132000, 8, 1.25, '/assets/products/yale-assure-3.jpg', 'The smart lock that welcomes you home. The Assure Lock 3 features a fingerprint-resistant touchscreen, voice assistant unlock, auto-lock when you leave, and Matter-over-Thread support that connects to any smart home ecosystem without a separate hub.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/yale-assure-3.jpg', 149000, 4.6, 1, 'Yale', 1, 1),

('eufy-smart-drop-delivery-box', 'eufy SmartDrop Delivery Box with Camera & App Control - Dark Grey', 'smart-home', 220000, 215000, 178000, 6, 8.5, '/assets/products/eufy-smartdrop.jpg', 'Secure your packages from porch pirates. This weatherproof delivery box features a built-in camera, a secure passcode system for couriers, and instant app notifications. The large 85L capacity handles multiple packages and even grocery deliveries.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/eufy-smartdrop.jpg', 205000, 4.4, 0, 'eufy', 1, 1),

('rachio-3-smart-sprinkler', 'Rachio 3 Smart Sprinkler Controller 16-Zone with Weather Intelligence', 'smart-home', 185000, 179000, 148000, 6, 0.85, '/assets/products/rachio-3.jpg', 'A lush garden without wasting a drop. The Rachio 3 uses hyperlocal weather data and plant-specific watering schedules to automatically adjust irrigation, saving up to 50% on outdoor water usage while keeping your garden vibrant through Nigerian dry seasons.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/rachio-3.jpg', 168000, 4.5, 0, 'Rachio', 1, 1),

-- OUTDOOR & CAMPING GEAR (10 products)
('yeti-roadie-48-cooler', 'YETI Roadie 48 Wheeled Cooler with Divider - Charcoal', 'outdoor', 380000, 369000, 315000, 4, 12.5, '/assets/products/yeti-roadie-48.jpg', 'Indestructible ice retention trusted by outdoor professionals. The Roadie 48 keeps ice frozen for days in Nigerian heat, features a heavy-duty wheeled cart design for easy transport, and is certified bear-resistant—built to outlast you.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/yeti-roadie-48.jpg', 348000, 4.8, 1, 'YETI', 1, 1),

('stanley-adventure-camp-cookset', 'Stanley Adventure Even-Heat Camp Cook Set 19-Piece - Stainless Steel', 'outdoor', 125000, 119000, 98000, 8, 3.2, '/assets/products/stanley-cookset.jpg', 'A complete kitchen that packs into a single pot. The 19-piece set includes plates, bowls, spatula, cutting board, and a 3-ply stainless steel pot with even-heat technology. Everything nests into the pot for compact storage. Dishwasher safe.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/stanley-cookset.jpg', 112000, 4.7, 1, 'Stanley', 1, 1),

('bioLite-campstove-3', 'BioLite CampStove 3 Wood-Burning USB Charger & Smokeless Fire Pit', 'outdoor', 185000, 179000, 148000, 6, 2.1, '/assets/products/biolite-campstove-3.jpg', 'Turn twigs and pinecones into electricity for your devices. The CampStove 3 burns any biomass fuel for cooking while converting heat into 5W of USB power via a thermoelectric generator. The integrated fan reduces smoke for a clean burn.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/biolite-campstove-3.jpg', 168000, 4.5, 1, 'BioLite', 1, 1),

('coleman-sundome-6p-tent', 'Coleman Sundome 6-Person Camping Tent with Dark Room Technology', 'outdoor', 185000, 179000, 148000, 6, 8.5, '/assets/products/coleman-sundome-6.jpg', 'Sleep in past sunrise with Dark Room technology that blocks 90% of sunlight and reduces tent temperature by up to 10°C. The 6-person Sundome features Coleman''s WeatherTec system with patented welded corners and inverted seams for guaranteed dryness.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/coleman-sundome-6.jpg', 168000, 4.4, 0, 'Coleman', 1, 1),

('thermacell-e90-rechargeable', 'Thermacell E90 Rechargeable Mosquito Repeller with 12-Hour Battery', 'outdoor', 35000, 33900, 28500, 20, 0.35, '/assets/products/thermacell-e90.jpg', 'Create a 20-foot mosquito-free zone without sprays, lotions, or open flames. The E90 uses a rechargeable lithium-ion battery and scent-free repellent mats that heat-activated to create an invisible shield—essential for Nigerian outdoor evenings.', 1, unixepoch('2026-06-16'), 1, 28500, '/assets/products/thermacell-e90.jpg', 31800, 4.6, 1, 'Thermacell', 1, 1),

('goal-zero-lighthouse-600', 'Goal Zero Lighthouse 600 Portable Lantern with USB-C Charging', 'outdoor', 45000, 43900, 36500, 12, 0.65, '/assets/products/goalzero-lighthouse-600.jpg', 'A lantern and power bank in one. The Lighthouse 600 outputs 600 lumens of warm LED light with a built-in hand crank for emergency charging, a 5,200mAh battery that charges your phone via USB-C, and a collapsible design that stows flat.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/goalzero-lighthouse-600.jpg', 41500, 4.5, 0, 'Goal Zero', 1, 1),

('osprey-farpoint-55-travel', 'Osprey Farpoint 55 Travel Backpack with Detachable Daypack - Black', 'outdoor', 185000, 179000, 148000, 6, 2.05, '/assets/products/osprey-farpoint-55.jpg', 'The definitive travel backpack system. The 55-liter main pack and detachable 15-liter daypack are carry-on compliant, feature a stowable harness and hip belt, and are built with Osprey''s legendary lifetime warranty. LightWire frame suspension carries heavy loads comfortably.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/osprey-farpoint-55.jpg', 168000, 4.8, 0, 'Osprey', 1, 1),

('leatherman-wave-plus-multitool', 'Leatherman Wave+ Stainless Steel Multitool with Nylon Sheath', 'outdoor', 85000, 82900, 68000, 15, 0.24, '/assets/products/leatherman-wave-plus.jpg', 'The multitool that defined an industry. 18 tools including pliers, wire cutters, knives, saw, file, scissors, and screwdrivers—all accessible with one hand. Made in the USA with a 25-year warranty, the Wave+ is trusted by professionals worldwide.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/leatherman-wave-plus.jpg', 78000, 4.8, 1, 'Leatherman', 1, 1),

('black-diamond-spot-450-headlamp', 'Black Diamond Spot 450 USB-C Rechargeable Headlamp - Azul Blue', 'outdoor', 38000, 36900, 30500, 20, 0.09, '/assets/products/bd-spot-450.jpg', '450 lumens of bright, customizable light with PowerTap technology that instantly transitions to full brightness. The waterproof IP67 rating handles Nigerian rainstorms, while the USB-C rechargeable battery eliminates disposable battery waste.', 1, unixepoch('2026-06-16'), 1, 30500, '/assets/products/bd-spot-450.jpg', 34800, 4.7, 1, 'Black Diamond', 1, 1),

('sea-to-summit-comfort-deluxe', 'Sea to Summit Comfort Deluxe Self-Inflating Sleeping Mat - Double', 'outdoor', 220000, 215000, 178000, 4, 3.8, '/assets/products/sts-comfort-deluxe.jpg', 'A bed-like sleeping experience in the wilderness. The 4-inch thick dual-layer foam mattress self-inflates to provide luxurious comfort with an R-value of 6.5 for four-season insulation. The oversized double size fits two adults comfortably.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/sts-comfort-deluxe.jpg', 205000, 4.7, 0, 'Sea to Summit', 1, 1),

-- PROFESSIONAL TOOLS & WORKSHOP (8 products)
('dremel-4300-rotary-tool', 'Dremel 4300 Variable Speed Rotary Tool Kit with 65 Accessories', 'tools', 125000, 119000, 98000, 8, 2.8, '/assets/products/dremel-4300.jpg', 'The most versatile rotary tool system for DIY, crafts, and professional work. The 4300 features a powerful 1.8A motor with electronic feedback for consistent speed under load, a quick-change chuck, and 65 genuine Dremel accessories in a durable carry case.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/dremel-4300.jpg', 112000, 4.7, 1, 'Dremel', 1, 1),

('dewalt-dcf850-impact-driver', 'DeWalt DCF850 20V MAX XR Brushless Impact Driver Kit with 2 Batteries', 'tools', 185000, 179000, 148000, 6, 3.5, '/assets/products/dewalt-dcf850.jpg', 'Professional-grade power in a compact design. The DCF850 delivers 2,400 in-lbs of torque and 3,800 RPM with a brushless motor that maximizes runtime. Includes two 5Ah batteries, a charger, and DeWALT''s 3-year limited warranty.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/dewalt-dcf850.jpg', 168000, 4.8, 1, 'DeWalt', 1, 1),

('bosch-glm-50-27cg-laser', 'Bosch GLM 50-27CG Professional Green-Beam Laser Measure with Camera', 'tools', 125000, 119000, 98000, 8, 0.25, '/assets/products/bosch-glm-50.jpg', 'Precision measurement down to 1.5mm accuracy at 50 meters. The built-in camera with zoom allows you to see the laser point on distant targets even in bright Nigerian sunlight, while Bluetooth transfers measurements directly to building plans on your phone.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/bosch-glm-50.jpg', 112000, 4.7, 0, 'Bosch', 1, 1),

('fluke-t6-1000-pro-tester', 'Fluke T6-1000 PRO Electrical Tester with FieldSense Technology', 'tools', 185000, 179000, 148000, 5, 0.38, '/assets/products/fluke-t6-1000.jpg', 'Measure voltage and current without touching live wires. Fluke''s patented FieldSense technology safely measures AC voltage, current, and frequency through the fork opening—no test leads needed. True RMS sensing ensures accurate readings on non-linear loads.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/fluke-t6-1000.jpg', 168000, 4.9, 0, 'Fluke', 1, 1),

('milwaukee-m18-inflator', 'Milwaukee M18 18V Cordless Tire Inflator with Digital Gauge', 'tools', 125000, 119000, 98000, 6, 2.1, '/assets/products/milwaukee-inflator.jpg', 'Professional-grade inflation without a compressor. This cordless inflator delivers up to 150 PSI, auto-stops at your preset pressure, and fills a car tire from flat to full in under 2 minutes. M18 battery compatible with all Milwaukee tools.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/milwaukee-inflator.jpg', 112000, 4.7, 1, 'Milwaukee', 1, 1),

('knipex-cobra-pliers-set', 'KNIPEX Cobra High-Tech Water Pump Pliers Set 3-Piece - 7/10/12 inch', 'tools', 65000, 63900, 52000, 10, 1.25, '/assets/products/knipex-cobra-set.jpg', 'German engineering that grips like no other. The self-locking Cobra design adjusts with one hand and maintains its grip on any shape without slipping. This 3-piece set covers every plumbing and mechanical task, with a lifetime of reliable service.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/knipex-cobra-set.jpg', 59000, 4.9, 0, 'KNIPEX', 1, 1),

('makita-dhp486-18v-drill', 'Makita DHP486 18V LXT Brushless Hammer Driver Drill Kit', 'tools', 220000, 215000, 178000, 5, 3.8, '/assets/products/makita-dhp486.jpg', 'Makita''s most powerful 18V hammer drill delivers 130Nm of torque for driving large fasteners and drilling through concrete, steel, and hardwood. The brushless motor and dual 5Ah batteries provide all-day runtime on demanding Nigerian job sites.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/makita-dhp486.jpg', 205000, 4.8, 0, 'Makita', 1, 1),

('wera-tool-check-plus', 'Wera Tool-Check Plus Metric Ratchet & Bit Set 39-Piece', 'tools', 55000, 53900, 45000, 12, 0.45, '/assets/products/wera-tool-check.jpg', 'A complete mobile workshop in your pocket. This compact case contains a mini ratchet, 28 bits, 7 sockets, and a bit holder with Wera''s iconic Kraftform handle. German-made with a lifetime warranty, trusted by mechanics and technicians worldwide.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/wera-tool-check.jpg', 50500, 4.8, 1, 'Wera', 1, 1),

-- CUTTING-EDGE PC PERIPHERALS (12 products)
('logitech-g-cloud-ii-handheld', 'Logitech G Cloud II Cloud Gaming Handheld 7" OLED 256GB', 'gaming', 320000, 315000, 268000, 6, 0.48, '/assets/products/logitech-g-cloud-2.jpg', 'Stream your Xbox, PlayStation, and PC games anywhere with WiFi 7 and a gorgeous 7-inch 120Hz OLED display. The G Cloud II features a Snapdragon G4 processor, 12-hour battery life, and precision Hall Effect joysticks for cloud gaming perfection.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/logitech-g-cloud-2.jpg', 298000, 4.6, 1, 'Logitech', 1, 1),

('razer-deathstalker-v3-pro-tkl', 'Razer DeathStalker V3 Pro TKL Wireless Gaming Keyboard - White', 'gaming', 220000, 215000, 178000, 6, 0.78, '/assets/products/razer-deathstalker-v3.jpg', 'The world''s thinnest wireless gaming keyboard with Razer''s fastest switches. Low-profile optical switches with 1.2mm actuation, a slim 26mm aluminum chassis, and HyperSpeed wireless with multi-device pairing set a new standard for competitive keyboards.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/razer-deathstalker-v3.jpg', 205000, 4.7, 1, 'Razer', 1, 1),

('asus-rog-azoth-extreme-75', 'ASUS ROG Azoth Extreme 75% Wireless Gaming Keyboard with OLED Display', 'gaming', 380000, 369000, 315000, 4, 1.35, '/assets/products/asus-azoth-extreme.jpg', 'The ultimate custom keyboard from ROG. A full CNC aluminum case houses hot-swappable ROG NX Snow switches, a gasket-mounted plate, and a 2-inch OLED display for system monitoring. The included lubing kit and switch opener invite endless customization.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/asus-azoth-extreme.jpg', 348000, 4.8, 0, 'ASUS', 1, 1),

('glorious-model-o-3-wireless', 'Glorious Model O 3 Wireless Gaming Mouse 68g - Matte White', 'gaming', 85000, 82900, 68000, 10, 0.07, '/assets/products/glorious-model-o-3.jpg', 'The legendary honeycomb mouse enters its third generation. At 68 grams with the BAMF 3.0 sensor tracking at 36,000 DPI, optical switches rated for 100 million clicks, and 210-hour battery life, the Model O 3 remains the choice of competitive FPS players.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/glorious-model-o-3.jpg', 78000, 4.7, 1, 'Glorious', 1, 1),

('corsair-k70-max-gaming-keyboard', 'Corsair K70 MAX Magnetic-Mechanical Gaming Keyboard with Rapid Trigger', 'gaming', 220000, 215000, 178000, 5, 1.25, '/assets/products/corsair-k70-max.jpg', 'Corsair''s first magnetic switch keyboard. Adjustable actuation points from 0.4mm to 3.6mm, Rapid Trigger for instant counter-strafing, and dual actuation points that bind two actions to a single key press. A game-changer for competitive keyboard enthusiasts.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/corsair-k70-max.jpg', 205000, 4.7, 1, 'Corsair', 1, 1),

('steelseries-aerox-9-wireless', 'SteelSeries Aerox 9 Wireless MMO/MOBA Gaming Mouse - Onyx Black', 'gaming', 125000, 119000, 98000, 8, 0.09, '/assets/products/steelseries-aerox-9.jpg', '12 programmable side buttons in a lightweight 89g package. The Aerox 9 is the ultimate MMO mouse with a TrueMove Air sensor, dual wireless connectivity, and an IP54 AquaBarrier rating that protects against sweat and spills during marathon gaming sessions.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/steelseries-aerox-9.jpg', 112000, 4.6, 0, 'SteelSeries', 1, 1),

('elgato-stream-deck-pedal-2', 'Elgato Stream Deck Pedal 2 Hands-Free Studio Controller', 'gaming', 85000, 82900, 68000, 8, 0.95, '/assets/products/elgato-pedal-2.jpg', 'Control your stream, music, or editing software with your feet. The three silent, adjustable pedals trigger macros, mute your mic, switch scenes, or control playback without taking your hands off the keyboard. Essential for musicians, streamers, and editors.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/elgato-pedal-2.jpg', 78000, 4.5, 1, 'Elgato', 1, 1),

